 @Test void suggestedRangesBalanceCohortsAndCanBeReshuffled()throws Exception {
  Layout tenSeats=new Layout(List.of(new Column(List.of(new Bench(2,List.of()),new Bench(2,List.of()),new Bench(2,List.of()),new Bench(2,List.of()),new Bench(2,List.of())))));
  Room a=room(tenSeats),b=room(tenSeats);a.name="603";b.id=2L;b.name="605";when(roomRepo.findAllById(List.of(1L,2L))).thenReturn(List.of(a,b));
  List<String> students=new ArrayList<>();for(int i=1;i<=16;i++)students.add("1BI24IS"+String.format("%03d",i));for(int i=400;i<=403;i++)students.add("1BI25IS"+i);
  var service=new AllocationService(roomRepo,examRepo);var first=service.suggestRanges(students,List.of(1L,2L));List<RoomRange> ranges=(List<RoomRange>)first.get("ranges");
  var assignments=service.generateByRanges(students,List.of(1L,2L),ranges);service.validate(assignments,students,List.of(1L,2L));
  for(Long roomId:List.of(1L,2L)){assertEquals(10,assignments.stream().filter(x->x.seat().roomId().equals(roomId)).count());assertEquals(8,assignments.stream().filter(x->x.seat().roomId().equals(roomId)&&x.usn().startsWith("1BI24IS")).count());assertEquals(2,assignments.stream().filter(x->x.seat().roomId().equals(roomId)&&x.usn().startsWith("1BI25IS")).count());}
  var second=service.suggestRanges(students,List.of(1L,2L),ranges);assertNotEquals(ranges,second.get("ranges"));
 }
 @Test void mixedSemesterPatternFillsTriplesThenPlacesRemainingStudentsNormally()throws Exception {
  Layout l=new Layout(List.of(new Column(List.of(new Bench(3,List.of()),new Bench(3,List.of())))));when(roomRepo.findAllById(List.of(1L))).thenReturn(List.of(room(l)));
  List<String> students=List.of("1BI24IS001","1BI24IS002","1BI24IS003","1BI24IS004","1BI25IS001","1BI25IS002");Map<String,String> groups=Map.of("1BI24IS001","3rd Semester","1BI24IS002","3rd Semester","1BI24IS003","3rd Semester","1BI24IS004","3rd Semester","1BI25IS001","5th Semester","1BI25IS002","5th Semester");
  var service=new AllocationService(roomRepo,examRepo);var ranges=List.of(new RoomRange(1L,"1BI24IS001","1BI25IS002"));var result=service.generateByRanges(students,List.of(1L),ranges,groups,"MIXED","B_A_B","3rd Semester","5th Semester");service.validate(result,students,List.of(1L),true);
  assertEquals("1BI25IS001",result.stream().filter(x->x.seat().bench()==1&&x.seat().position()==1).findFirst().orElseThrow().usn());
  assertEquals("1BI24IS001",result.stream().filter(x->x.seat().bench()==1&&x.seat().position()==2).findFirst().orElseThrow().usn());
  assertEquals("1BI25IS002",result.stream().filter(x->x.seat().bench()==1&&x.seat().position()==3).findFirst().orElseThrow().usn());
  assertTrue(result.stream().filter(x->x.seat().bench()==2).allMatch(x->groups.get(x.usn()).equals("3rd Semester")));
  var reverse=service.generateByRanges(students,List.of(1L),ranges,groups,"MIXED","A_B_A","3rd Semester","5th Semester");assertEquals("1BI24IS001",reverse.stream().filter(x->x.seat().bench()==1&&x.seat().position()==1).findFirst().orElseThrow().usn());assertEquals("1BI25IS001",reverse.stream().filter(x->x.seat().bench()==1&&x.seat().position()==2).findFirst().orElseThrow().usn());assertEquals("1BI24IS002",reverse.stream().filter(x->x.seat().bench()==1&&x.seat().position()==3).findFirst().orElseThrow().usn());
 }
