  var service=new AllocationService(roomRepo,examRepo);List<RoomRange> ranges=List.of(new RoomRange(1L,"1BI24IS001","1BI25IS008"));var result=service.generateByRanges(eligible,List.of(1L),ranges,groups,"MIXED","A_B_A","3rd Semester","5th Semester");service.validate(result,eligible,List.of(1L),true);service.validateRanges(result,ranges);service.validateMixedPairing(result,groups,List.of(1L));
  for(int bench=1;bench<=5;bench++){int targetBench=bench;List<Assignment> occupants=result.stream().filter(a->a.seat().column().equals("C2")&&a.seat().bench()==targetBench).toList();assertEquals(2,occupants.size(),"middle-column bench "+bench);assertEquals(2,occupants.stream().map(a->groups.get(a.usn())).distinct().count(),"middle-column bench "+bench);}
