 @Test void crossSemesterPairsAreMaximizedBeforeSameSemesterFallback()throws Exception {
  Room lab=room(new Layout(List.of(new Column(List.of(new Bench(2,List.of()),new Bench(2,List.of()))))));lab.mode="SPECIAL";when(roomRepo.findAllById(List.of(1L))).thenReturn(List.of(lab));List<String> students=List.of("1BI24IS001","1BI24IS002","1BI24IS003","1BI25IS001");Map<String,String> groups=Map.of(students.get(0),"3rd Semester",students.get(1),"3rd Semester",students.get(2),"3rd Semester",students.get(3),"5th Semester");var service=new AllocationService(roomRepo,examRepo);var result=service.generateByRanges(students,List.of(1L),List.of(new RoomRange(1L,"1BI24IS001","1BI25IS001")),groups,"MIXED","A_B_A","3rd Semester","5th Semester");service.validateMixedPairing(result,groups,List.of(1L));long cross=result.stream().collect(java.util.stream.Collectors.groupingBy(a->a.seat().bench())).values().stream().filter(bench->bench.size()==2&&bench.stream().map(a->groups.get(a.usn())).distinct().count()==2).count();assertEquals(1,cross);assertEquals(4,result.size());
 }
 @Test void threePositionBenchesUseRoomCohortProportionsInsteadOfFixedTwoToOne()throws Exception {
  Room regular=room(new Layout(List.of(new Column(List.of(new Bench(3,List.of()),new Bench(3,List.of()),new Bench(3,List.of()),new Bench(3,List.of()))))));regular.mode="DEFAULT";when(roomRepo.findAllById(List.of(1L))).thenReturn(List.of(regular));List<String> students=new ArrayList<>();Map<String,String> groups=new HashMap<>();for(int i=1;i<=10;i++){String usn="1BI24IS"+String.format("%03d",i);students.add(usn);groups.put(usn,"3rd Semester");}for(int i=1;i<=2;i++){String usn="1BI25IS"+String.format("%03d",i);students.add(usn);groups.put(usn,"5th Semester");}var service=new AllocationService(roomRepo,examRepo);var result=service.generateByRanges(students,List.of(1L),List.of(new RoomRange(1L,"1BI24IS001","1BI25IS002")),groups,"MIXED","A_B_A","3rd Semester","5th Semester");service.validate(result,students,List.of(1L),true);assertEquals(10,result.stream().filter(a->groups.get(a.usn()).equals("3rd Semester")).count());assertEquals(2,result.stream().filter(a->groups.get(a.usn()).equals("5th Semester")).count());long allA=result.stream().collect(java.util.stream.Collectors.groupingBy(a->a.seat().bench())).values().stream().filter(bench->bench.size()==3&&bench.stream().allMatch(a->groups.get(a.usn()).equals("3rd Semester"))).count();assertTrue(allA>0,"substantially unequal cohorts should produce some same-semester triples");
 }
 @Test void generatedRoom612AssignmentsAreSavedAndReloadWithoutSameSemesterPairs()throws Exception {
  List<Column> columns=List.of(new Column(java.util.stream.IntStream.range(0,5).mapToObj(i->new Bench(3,List.of(),2)).toList()),new Column(java.util.stream.IntStream.range(0,5).mapToObj(i->new Bench(2,List.of(),1)).toList()),new Column(java.util.stream.IntStream.range(0,5).mapToObj(i->new Bench(3,List.of(),2)).toList()));Room lab=room(new Layout(columns));lab.mode="SPECIAL";when(roomRepo.findAllById(List.of(1L))).thenReturn(List.of(lab));List<String> eligible=new ArrayList<>();Map<String,String> groups=new HashMap<>();for(int i=1;i<=8;i++){String usn="1BI24IS"+String.format("%03d",i);eligible.add(usn);groups.put(usn,"3rd Semester");}for(int i=1;i<=8;i++){String usn="1BI25IS"+String.format("%03d",i);eligible.add(usn);groups.put(usn,"5th Semester");}
  Exam exam=new Exam();exam.id=7L;exam.name="Room 612 verification";exam.studentsJson=Json.write(eligible);exam.studentGroupsJson=Json.write(groups);exam.roomIdsJson=Json.write(List.of(1L));exam.rangeRulesJson=Json.write(List.of(new RoomRange(1L,"1BI24IS001","1BI25IS008")));exam.seatingMode="MIXED";exam.semester="3rd Semester";exam.semesterB="5th Semester";exam.mixPattern="A_B_A";when(examRepo.findById(7L)).thenReturn(Optional.of(exam));when(examRepo.save(any())).thenAnswer(invocation->invocation.getArgument(0));AllocationService service=new AllocationService(roomRepo,examRepo);ApiController controller=new ApiController(roomRepo,examRepo,service,new StudentImportService());
  Map<String,Object> generated=controller.generate(7L,false);assertEquals(16,generated.get("assigned"));Exam saved=controller.save(7L);Exam reloaded=controller.exam(7L);assertTrue(saved.saved);List<Assignment> persisted=Json.assignments(reloaded.assignmentsJson);service.validate(persisted,eligible,List.of(1L),true);service.validateRanges(persisted,Json.read(reloaded.rangeRulesJson,new com.fasterxml.jackson.core.type.TypeReference<List<RoomRange>>(){}));service.validateMixedPairing(persisted,groups,List.of(1L));for(int bench=1;bench<=5;bench++){int targetBench=bench;List<Assignment> occupants=persisted.stream().filter(a->a.seat().column().equals("C2")&&a.seat().bench()==targetBench).toList();assertEquals(2,occupants.size());assertEquals(2,occupants.stream().map(a->groups.get(a.usn())).distinct().count());}String chosen= reloaded.assignmentsJson;Map<String,Object> again=controller.generate(7L,true);assertEquals(chosen,reloaded.assignmentsJson,"Arrange again must preserve the saved arrangement until the proposal is chosen");controller.assignments(7L,Map.of("assignments",again.get("assignments")));controller.save(7L);Exam reloadedAgain=controller.exam(7L);assertEquals(Json.write(again.get("assignments")),reloadedAgain.assignmentsJson);service.validate(Json.assignments(reloadedAgain.assignmentsJson),eligible,List.of(1L),true);service.validateMixedPairing(Json.assignments(reloadedAgain.assignmentsJson),groups,List.of(1L));
 }
